"""Demo: strict ascent of the Boolean support-below-n staircase in F_2^N."""
from __future__ import annotations
from typing import FrozenSet


def in_suppLt(f: FrozenSet[int], n: int) -> bool:
    """Membership in I_n = {f : f(i)=0 for all i>=n}."""
    return all(i < n for i in f)


def indicator(n: int) -> FrozenSet[int]:
    """The bit-sequence that is 1 at position n and 0 elsewhere."""
    return frozenset({n})


def certify_strict_ascent(steps: int = 8) -> None:
    for n in range(steps):
        e = indicator(n)
        strict = in_suppLt(e, n + 1) and not in_suppLt(e, n)
        print(f"I_{n} \u2282 I_{n+1} strict? {strict}  (witness e_{n})")


if __name__ == "__main__":
    certify_strict_ascent()

"""Demo: finite verification of the Loop-Back Lemma in F_2^N."""
from __future__ import annotations
from typing import FrozenSet, List, Set


def in_suppLt(f: FrozenSet[int], n: int) -> bool:
    return all(i < n for i in f)


def loop_back(universe_bound: int = 8, N: int = 6) -> bool:
    all_seqs: List[FrozenSet[int]] = [
        frozenset(i for i in range(universe_bound) if (mask >> i) & 1)
        for mask in range(1 << universe_bound)
    ]
    inter: Set[FrozenSet[int]] = set(all_seqs)
    for n in range(N + 1):
        inter &= {f for f in all_seqs if in_suppLt(f, n)}
    return inter == {frozenset()}


if __name__ == "__main__":
    print("Intersection equals I_0 = {0}:", loop_back())

"""Demo: the dyadic Anti-Escher collapse ∩_n (2^n) = {0} in Z."""
from __future__ import annotations
from typing import List


def two_adic_valuation(x: int) -> int:
    """Largest n with 2^n | x (x != 0)."""
    n = 0
    while x % 2 == 0:
        x //= 2
        n += 1
    return n


def exit_stages(samples: List[int]) -> None:
    for x in samples:
        v = two_adic_valuation(x)
        print(f"x={x}: in (2^{v}), out of (2^{v+1}); exits chain at stage {v+1}")


if __name__ == "__main__":
    exit_stages([6, 24, 40, 1024, 7, -96])

